css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 6px 12px; margin-bottom: 7px;}
.mz .recuerda-titulo{font-size: 12.5px; font-weight: 700; margin-bottom: 4px; display: flex; align-items: center; gap: 6px;}
.mz .recuerda-idea{font-size: 12px; margin-bottom: 5px; line-height: 1.3;}
.mz .recuerda-ejemplo{display: flex; justify-content: center;}
.mz .tabla-ej{border-collapse: collapse; font-size: 13px;}
.mz .tabla-ej th,.mz .tabla-ej td{border: 1.5px solid var(--bosque); padding: 3px 14px; text-align: center; font-weight: 700;}
.mz .tabla-ej th{background: #f3f3f3; font-size: 11.5px; font-family: sans-serif;}
.mz .tabla-ej svg{width: 22px; height: 22px; vertical-align: middle;}
.mz .e1-wrap{display: grid; grid-template-columns: 1fr auto; gap: 14px; align-items: center;}
.mz .mosaico{border: 2px solid var(--bosque); border-radius: 10px; padding: 8px; display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; justify-items: center; align-items: center;}
.mz .mosaico svg{width: 32px; height: 32px;}
.mz .tabla-rellenar{border-collapse: collapse; font-size: 13px;}
.mz .tabla-rellenar th,.mz .tabla-rellenar td{border: 1.5px solid var(--bosque); padding: 5px 12px; text-align: center; font-weight: 700;}
.mz .tabla-rellenar th{background: #f3f3f3; font-size: 11.5px; font-family: sans-serif;}
.mz .tabla-rellenar svg{width: 22px; height: 22px; vertical-align: middle;}
.mz .tabla-rellenar .hueco{min-width: 36px; height: 20px;}
.mz .e2-wrap{display: grid; grid-template-columns: auto 1fr; gap: 14px; align-items: center;}
.mz .preg-lista{display: flex; flex-direction: column; gap: 4px;}
.mz .preg-fila{font-size: 12px; line-height: 1.35;}
.mz .preg-hueco{display: inline-block; min-width: 36px; border-bottom: 1.5px solid var(--bosque); height: 18px; vertical-align: middle; margin-left: 4px;}
.mz .preg-hueco-grande{display: inline-block; min-width: 80px; border-bottom: 1.5px solid var(--bosque); height: 18px; vertical-align: middle; margin-left: 4px;}
.mz .rodear-fila{display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px;}
.mz .rodear-caja{border: 1.5px dashed #000; border-radius: 8px; padding: 6px; display: flex; align-items: center; justify-content: center; min-height: 56px;}
.mz .rodear-caja svg{width: 44px; height: 44px;}
.mz .e4-wrap{display: grid; grid-template-columns: auto 1fr; gap: 14px; align-items: stretch;}
.mz .dibujar-zona{border: 2px solid var(--bosque); border-radius: 10px; padding: 8px; display: grid; grid-template-rows: repeat(3, 1fr); gap: 5px;}
.mz .dibujar-fila{display: grid; grid-template-columns: 30px 1fr; gap: 8px; align-items: center; border-bottom: 1px dashed #999; padding-bottom: 4px;}
.mz .dibujar-fila:last-child{border-bottom: none; padding-bottom: 0;}
.mz .dibujar-fila svg{width: 26px; height: 26px;}
.mz .dibujar-fila .zona-libre{height: 28px;}
.mz .preg-fila,.mz .recuerda-idea{line-height: 1.875 !important;}
